esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// pgbouncer_up is a gauge: 1 = the pooler answered its admin console, 0 = it did not.
// MIN() across series so one unhealthy scrape target is not masked by a healthy one.
| STATS `PgBouncer Up` = MIN(LAST_OVER_TIME(pgbouncer_up))
    BY resource.attributes.supabase_project_ref
// Projects on the shared Supavisor pooler emit no pgbouncer_* series at all, so this
// query returns no rows for them rather than a false breach.
| WHERE `PgBouncer Up` == 0
